B.af1=new A.cP("\u0627\u0644\u0645\u062f \u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u0645\u062a\u0635\u0644","\u062d\u0631\u0641 \u0645\u062f \u0628\u0639\u062f\u0647 \u0647\u0645\u0632\u0629 \u0641\u064a \u0627\u0644\u0643\u0644\u0645\u0629 \u0646\u0641\u0633\u0647\u0627\u060c \u0648\u064a\u064f\u0645\u062f \u0623\u0631\u0628\u0639 \u0623\u0648 \u062e\u0645\u0633 \u062d\u0631\u0643\u0627\u062a.","\u0644\u0627 \u062a\u0642\u0635\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u062f\u061b \u0623\u0637\u0650\u0644\u0647 \u0642\u0628\u0644 \u0646\u0637\u0642 \u0627\u0644\u0647\u0645\u0632\u0629.")
B.afm=new A.cP("Obligatory madd (muttasil)","A madd letter followed by hamza in the same word, lengthened for four or five counts.","Don't shorten it; stretch it before saying the hamza.")
B.a84=new A.W(B.bE,[B.af1,B.afm],t.c)
B.afp=new A.cP("\u0627\u0644\u0645\u062f \u0627\u0644\u0644\u0627\u0632\u0645","\u062d\u0631\u0641 \u0645\u062f \u0628\u0639\u062f\u0647 \u0633\u0643\u0648\u0646 \u0623\u0635\u0644\u064a\u060c \u0648\u064a\u064f\u0645\u062f \u0633\u062a \u062d\u0631\u0643\u0627\u062a.","\u0645\u062f\u0651\u0647 \u0633\u062a \u062d\u0631\u0643\u0627\u062a \u0643\u0627\u0645\u0644\u0629.")
B.af9=new A.cP("Necessary madd (lazim)","A madd letter followed by an original sukoon, lengthened for six counts.","Stretch it for a full six counts.")
B.a7W=new A.W(B.bE,[B.afp,B.af9],t.c)
